Here is the root cause:
The mempolicy object was freed immediately via kmem_cache_free() in __mpol_put() without any RCU grace period, while the speculative futex path (futex_key_to_node_opt()) reads vma->vm_policy under RCU read-side lock. This allowed a concurrent vma_replace_policy() to free the mempolicy before the speculative reader finishes accessing it, causing a use-after-free when __futex_key_to_node() dereferences mpol->mode. Also, the absence of READ_ONCE/WRITE_ONCE for vm_policy accesses contributed to the race.

Here is the patch:
 /* Slow path of a mpol destructor. */
 void __mpol_put(struct mempolicy *pol)
 {
 	if (!atomic_dec_and_test(&pol->refcnt))
 		return;
-	kmem_cache_free(policy_cache, pol);
+	/*
+	 * Required to allow mmap_lock_speculative*() access, see for example
+	 * futex_key_to_node_opt(). All accesses are serialized by mmap_lock,
+	 * however the speculative lock section unbound by the normal lock
+	 * boundaries, requiring RCU freeing.
+	 */
+	kfree_rcu(pol, rcu);
 }
 EXPORT_SYMBOL_FOR_MODULES(__mpol_put, "kvm");
  */
 static int vma_replace_policy(struct vm_area_struct *vma,
 				struct mempolicy *pol)
 {
 	int err;
 	struct mempolicy *old;
 	struct mempolicy *new;

 	vma_assert_write_locked(vma);

 	new = mpol_dup(pol);
 	if (IS_ERR(new))
 		return PTR_ERR(new);

 	if (vma->vm_ops && vma->vm_ops->set_policy) {
 		err = vma->vm_ops->set_policy(vma, new);
 		if (err)
 			goto err_out;
 	}

 	old = vma->vm_policy;
-	vma->vm_policy = new; /* protected by mmap_lock */
+	WRITE_ONCE(vma->vm_policy, new); /* protected by mmap_lock */
 	mpol_put(old);

 	return 0;
  err_out:
 	mpol_put(new);
 	return err;
 }



